love:{type:'word',mode:'both',noun:'「好き」',unit:'回',fin:function(n){return n>1?'「好き」と'+n+'回ずつ言い合わないと':'「好き」と言い合わないと';},mid:function(n){return n>1?'「好き」と'+n+'回ずつ言い合って':'「好き」と言い合って';}},
