return{cat:rel==='before'?'bond':'romance',text:ctx.t(q3(ctx.pick(pool)),a,b),why:a.name+'と'+b.name+'は同一人物で、二人だけで閉じ込められた（'+DUO_LABEL[rel]+'）',mag:10};
