var mate=ctx.most(ctx.others(a).filter(function(o){return free(o)&& !HK.ngPair(a,o)&&R(ctx,a,o).ten<40&&R(ctx,o,a).ten<40&&R(ctx,a,o).aff>5&&R(ctx,o,a).aff>5;}),function(o){return R(ctx,a,o).aff+R(ctx,o,a).aff;});
