function rebelWill(c){return(c.goal.id==='truth'?0.5:0)+(c.goal.id==='nokill'?0.3:0)+(/exit|unite/.test(c.action.id)?0.2:0)+c.tr.lead*0.3+c.tr.a*0.2-c.tr.cold*0.2;}
