ctx.act2({actors:[trR],cat:'betray',mag:16,text:ctx.t(ctx.pick(TR_HINDER),trR),why:'裏切り者の'+trR.name+'が、黒幕に命じられて脱出の計画を崩した（反撃の進捗 -'+Math.round(lostH)+'）'});
