var FIELD=[['文学',function(t){return t.fc*0.4+t.np*0.3;}],['理論物理学',function(t){return t.a*0.7;}],['分子生物学',function(t){return t.a*0.5+t.ac*0.2;}],['心理学',function(t){return t.np*0.5+t.a*0.3;}],['歴史学',function(t){return t.cp*0.4+t.a*0.3;}],['数学',function(t){return t.a*0.6+t.cold*0.3;}],['経済学',function(t){return t.cp*0.4+t.a*0.4;}],['哲学',function(t){return t.a*0.4+(1-t.fc)*0.3;}],['第二性学',function(t){return t.np*0.3+t.a*0.4;}]];
