ctx.act2({actors:[reader],cat:'solo',fx:function(){P.forEach(function(o){ctx.stress(o,12);});},
text:ctx.t('{a}が日記を読み上げた。前の漂流者たちは、最後の十日間で互いを疑い始め、一人ずつ減っていったらしい。',reader),why:'島に流れ着いた過去の記録'});
